  const current = active?.label ?? inputs[0]?.label ?? labels.microphone
  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger
        aria-label={`${labels.chooseMic}: ${current}`}
        className="-mr-1.5 flex min-w-0 items-center gap-1 rounded-md px-1.5 py-1 text-xs font-medium text-muted-foreground transition-colors outline-none hover:bg-foreground/5 hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/30 data-popup-open:bg-foreground/5 data-popup-open:text-foreground"
      >
        <MicrophoneIcon
          className="size-3 shrink-0"
          weight="fill"
          aria-hidden="true"
        />
        <span className="max-w-48 truncate sm:max-w-64">{current}</span>
        <CaretDownIcon
          className="size-3 shrink-0"
          weight="bold"
          aria-hidden="true"
        />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-auto max-w-80 min-w-56">
        <DropdownMenuGroup>
          <DropdownMenuLabel className="text-xs text-muted-foreground">
            {labels.microphone}
          </DropdownMenuLabel>
          <DropdownMenuRadioGroup
            value={active?.deviceId ?? ""}
            onValueChange={(value) => onChoose(String(value))}
          >
            {inputs.map((input) => (
              <DropdownMenuRadioItem
                key={input.deviceId}
                value={input.deviceId}
              >
                <span className="truncate">{input.label}</span>
                {input.isDefault && (
                  <span className="shrink-0 text-xs text-muted-foreground">
                    {labels.systemDefault}
                  </span>
                )}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

// ── Hooks ──

/**
 * The thinking glow: the lobes gather into one beam that sweeps the edge
 * while the take is transcribed, and spread back out when it lands.
 */
function useProcessingMotion(active: boolean) {
  const state = useRef({ gather: 0, offset: 0, dir: 1, last: 0 })

  return useCallback((): VoiceBeamMotion | null => {
    const now = performance.now()
    const motion = state.current
    const dt = motion.last ? Math.min(0.05, (now - motion.last) / 1000) : 0.016
    motion.last = now
    const target = active ? 1 : 0
    motion.gather += (target - motion.gather) * Math.min(1, dt * 2.4)
    if (motion.gather > 0.08) {
      motion.offset += motion.dir * dt * 0.62
      if (motion.offset > 0.78) {
        motion.offset = 0.78
        motion.dir = -1
      } else if (motion.offset < -0.78) {
        motion.offset = -0.78
        motion.dir = 1
      }
    } else {
      motion.offset *= 1 - Math.min(1, dt * 3)
    }
    if (motion.gather < 0.02 && !active) return null
    return {
      gather: motion.gather,
      offset: motion.offset,
      stretch: 0.18,
      heldLevel: 0.58,
      cornerFollow: 0.4,
    }
  }, [active])
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false)
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)")
    const update = () => setReduced(query.matches)
    const initial = window.setTimeout(update, 0)
    query.addEventListener("change", update)
    return () => {
      window.clearTimeout(initial)
      query.removeEventListener("change", update)
    }
  }, [])
  return reduced
}

/** Light or dark, from the `.dark` class shadcn themes put on <html>. */
function useDocumentTheme(override?: "light" | "dark") {
  const [theme, setTheme] = useState<"light" | "dark">("light")
  useEffect(() => {
    if (override) return
    const root = document.documentElement
    const update = () =>
      setTheme(root.classList.contains("dark") ? "dark" : "light")
    const initial = window.setTimeout(update, 0)
    const observer = new MutationObserver(update)
    observer.observe(root, { attributes: true, attributeFilter: ["class"] })
    return () => {
      window.clearTimeout(initial)
      observer.disconnect()
    }
  }, [override])
  return override ?? theme
}

"use client"

/**
 * Voice Input — the live waveform drawn while recording and the playback
 * player shown after. Both paint in `currentColor`, so they follow whatever
 * text colour the parent sets.
 *
 * Part of the Launch Studio Labs Voice Input component.
 * https://labs.launchstudio.space/voice-input
 */

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type PointerEvent,
} from "react"
import { PauseIcon, PlayIcon } from "@phosphor-icons/react"
import { getAudioContext } from "voice-glow"

import { cn } from "@/lib/utils"
import {
  barHeight,
  clampTime,
  computePeaks,
  formatElapsed,
  formatPlayback,
  resamplePeaks,
  seekForKey,
  seekFromPointer,
} from "@/lib/voice-recording"

/**
 * - `bars`: a scrolling history of the level, newest on the right — reads as
 *   "this is being kept", the way a voice memo does
 * - `wave`: the live signal as one line — reads as "this is listening"
 * - `dots`: the same history as dots, quieter than bars
 */
export type VoiceWaveformStyle = "bars" | "wave" | "dots"

const BAR = { bars: 3, dots: 3 } as const
const GAP = { bars: 2, dots: 3 } as const
/** A new bar enters this often, so the history scrolls at a steady pace. */
const BAR_EVERY_MS = 70

export interface LiveWaveformProps extends ComponentProps<"div"> {
  analyser: AnalyserNode | null
  /** Smoothed 0–1 level, sampled per frame. */
  getLevel: () => number
  /** Hold the picture where it is (a paused take). */
  frozen?: boolean
  waveform?: VoiceWaveformStyle
}

/**
 * The signal while a take runs, on a canvas so it costs one paint per frame
 * and no React renders.
 */
export function LiveWaveform({
  analyser,
  getLevel,
  frozen = false,
  waveform = "bars",
  className,
  ...props
}: LiveWaveformProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const frozenRef = useRef(frozen)
  useEffect(() => {
    frozenRef.current = frozen
  }, [frozen])

  useEffect(() => {
    const canvas = canvasRef.current
    const context = canvas?.getContext("2d")
    if (!canvas || !context) return

    let width = 0
    let height = 0
    let color = "currentColor"
    const resize = () => {
      const rect = canvas.getBoundingClientRect()
      const ratio = window.devicePixelRatio || 1
      width = rect.width
      height = rect.height
      canvas.width = Math.round(width * ratio)
      canvas.height = Math.round(height * ratio)
      context.setTransform(ratio, 0, 0, ratio, 0, 0)
      color = getComputedStyle(canvas).color
    }
    resize()
    const observer = new ResizeObserver(resize)
    observer.observe(canvas)

    const samples = analyser ? new Float32Array(analyser.fftSize) : null
    const history: number[] = []
    let lastPush = 0
    let raf = 0
    let frame = 0

    const draw = (now: number) => {
      raf = requestAnimationFrame(draw)
      // Colour follows theme switches without a style read every frame.
      if (++frame % 30 === 0) color = getComputedStyle(canvas).color
      if (frozenRef.current && frame > 1) return

      context.clearRect(0, 0, width, height)
      context.fillStyle = color
      context.strokeStyle = color
      const mid = height / 2

      if (waveform === "wave") {
        context.lineWidth = 1.5
        context.lineJoin = "round"
        context.beginPath()
        if (analyser && samples) {
          analyser.getFloatTimeDomainData(samples)
          // Boost so a normal voice fills the lane; auto gain keeps it level.
          const gain = Math.min(6, 0.9 / Math.max(0.05, peakAbs(samples)))
          const step = samples.length / Math.max(1, width)
          for (let x = 0; x <= width; x++) {
            const value = samples[Math.floor(x * step)] ?? 0
            // Taper the ends so the line enters and leaves at the centre.
            const edge = Math.sin((x / width) * Math.PI)
            const y = mid + value * gain * mid * 0.9 * edge
            if (x === 0) context.moveTo(x, y)
            else context.lineTo(x, y)
          }
        } else {
          context.moveTo(0, mid)
          context.lineTo(width, mid)
        }
        context.stroke()
        return
      }

      const bar = BAR[waveform]
      const gap = GAP[waveform]
      const count = Math.max(1, Math.floor((width + gap) / (bar + gap)))
      if (now - lastPush >= BAR_EVERY_MS) {
        lastPush = now
        history.push(getLevel())
        if (history.length > count) history.splice(0, history.length - count)
      }
      for (let i = 0; i < count; i++) {
        // Newest on the right; the lane fills from the right edge.
        const level = history[history.length - count + i] ?? 0
        const x = i * (bar + gap)
        if (waveform === "dots") {
          const r = bar / 2
          const spread = level * (mid - r)
          context.globalAlpha = 0.35 + level * 0.65
          context.beginPath()
          context.arc(x + r, mid - spread * 0.5, r, 0, Math.PI * 2)
          context.arc(x + r, mid + spread * 0.5, r, 0, Math.PI * 2)
          context.fill()
        } else {
          const h = Math.max(bar, barHeight(level, 0.1) * height)
          context.globalAlpha = 1
          roundRect(context, x, mid - h / 2, bar, h, bar / 2)
        }
      }
      context.globalAlpha = 1
    }
    raf = requestAnimationFrame(draw)

    return () => {
      cancelAnimationFrame(raf)
      observer.disconnect()
    }
  }, [analyser, getLevel, waveform])

  return (
    <div
      data-slot="voice-live-waveform"
      aria-hidden="true"
      className={cn("relative h-6 min-w-0", className)}
      {...props}
    >
      <canvas ref={canvasRef} className="absolute inset-0 size-full" />
    </div>
  )
}

function peakAbs(samples: Float32Array) {
  let peak = 0
  for (let i = 0; i < samples.length; i++) {
    const value = Math.abs(samples[i])
    if (value > peak) peak = value
  }
  return peak
}

function roundRect(
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number
) {
  context.beginPath()
  if (context.roundRect) context.roundRect(x, y, w, h, r)
  else context.rect(x, y, w, h)
  context.fill()
}

// ── Playback ──

/** Peaks kept per recording; bars on screen are resampled from these. */
const PEAK_RESOLUTION = 1200
/** Voice needs nothing above 12 kHz; decoding at 24 kHz halves the memory. */
const DECODE_RATE = 24_000
const TRACK_HEIGHT = 28

type Load =
  | { state: "loading" }
  | { state: "ready"; buffer: AudioBuffer; peaks: number[] }
  | { state: "failed" }

export interface VoicePlayerLabels {
  play: string
  pause: string
  position: string
}

export interface VoicePlayerProps extends Omit<
  ComponentProps<"div">,
  "children"
> {
  /** The recording: a Blob from this session or a URL to a stored file. */
  source: Blob | string
  /** Shown before the audio decodes (and if it never does). */
  durationMs?: number | null
  waveform?: VoiceWaveformStyle
  labels?: Partial<VoicePlayerLabels>
}

const PLAYER_LABELS: VoicePlayerLabels = {
  play: "Play recording",
  pause: "Pause recording",
  position: "Playback position",
}

/**
 * A recording's waveform with play/pause and a scrubbable timeline. Plays
 * through Web Audio from the decoded buffer, so MediaRecorder WebM (no
 * duration, no cues) and Safari's MP4 seek the same.
 *
 * Remount it (a `key`) for a new recording.
 */
export function VoicePlayer({
  source,
  durationMs = null,
  waveform = "bars",
  labels: labelOverrides,
  className,
  ...props
}: VoicePlayerProps) {
  const labels = { ...PLAYER_LABELS, ...labelOverrides }
  const [load, setLoad] = useState<Load>({ state: "loading" })
  const [playing, setPlaying] = useState(false)
  const [second, setSecond] = useState(0)
  const [width, setWidth] = useState(0)

  const trackRef = useRef<HTMLDivElement | null>(null)
  const playedRef = useRef<HTMLDivElement | null>(null)
  const timeRef = useRef<HTMLSpanElement | null>(null)
  const nodeRef = useRef<AudioBufferSourceNode | null>(null)
  /** Position in seconds while paused; where playback started while playing. */
  const offsetRef = useRef(0)
  const startedAtRef = useRef(0)
  const rafRef = useRef(0)
  const dragRef = useRef<{ resume: boolean } | null>(null)

  // Decode once per recording.
  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const bytes =
          typeof source === "string"
            ? await fetch(source).then((res) => {
                if (!res.ok) throw new Error(String(res.status))
                return res.arrayBuffer()
              })
            : await source.arrayBuffer()
        const buffer = await decode(bytes)
        if (cancelled) return
        const channels = Array.from(
          { length: buffer.numberOfChannels },
          (_, i) => buffer.getChannelData(i)
        )
        setLoad({
          state: "ready",
          buffer,
          peaks: computePeaks(channels, PEAK_RESOLUTION),
        })
      } catch {
        if (!cancelled) setLoad({ state: "failed" })
      }
    })()
    return () => {
      cancelled = true
    }
  }, [source])

  // Bars follow the track's width.
  useEffect(() => {
    const track = trackRef.current
    if (!track) return
    const observer = new ResizeObserver(([entry]) => {
      setWidth(Math.floor(entry.contentRect.width))
    })
    observer.observe(track)
    return () => observer.disconnect()
  }, [])

  const duration =
    load.state === "ready" ? load.buffer.duration : (durationMs ?? 0) / 1000

  const currentTime = useCallback(() => {
    const node = nodeRef.current
    const context = node?.context
    if (!node || !context) return offsetRef.current
    return clampTime(
      offsetRef.current + (context.currentTime - startedAtRef.current),
      duration
    )
  }, [duration])

  const paint = useCallback(
    (time: number) => {
      const fraction = duration > 0 ? time / duration : 0
      if (playedRef.current) {
        playedRef.current.style.clipPath = `inset(0 ${(1 - fraction) * 100}% 0 0)`
      }
      if (timeRef.current) {
        timeRef.current.textContent = formatPlayback(time, duration)
      }
      const whole = Math.floor(time)
      setSecond((prev) => (prev === whole ? prev : whole))
    },
    [duration]
  )

  const stopNode = useCallback(() => {
    cancelAnimationFrame(rafRef.current)
    const node = nodeRef.current
    nodeRef.current = null
    if (node) {
      node.onended = null
      try {
        node.stop()
      } catch {
        // Already stopped.
      }
      node.disconnect()
    }
  }, [])

  const startAt = useCallback(
    (time: number) => {
      if (load.state !== "ready") return
      const context = getAudioContext()
      if (!context) return
      stopNode()
      if (context.state === "suspended") void context.resume()
      const from = time >= duration - 0.05 ? 0 : clampTime(time, duration)
      const node = context.createBufferSource()
      node.buffer = load.buffer
      node.connect(context.destination)
      node.onended = () => {
        if (nodeRef.current !== node) return
        nodeRef.current = null
        cancelAnimationFrame(rafRef.current)
        offsetRef.current = 0
        setPlaying(false)
        paint(duration)
        // Rest at the start after a short beat at the end.
        window.setTimeout(() => {
          if (!nodeRef.current) paint(0)
        }, 400)
      }
      offsetRef.current = from
      startedAtRef.current = context.currentTime
      node.start(0, from)
      nodeRef.current = node
      setPlaying(true)
      const tick = () => {
        paint(currentTime())
        rafRef.current = requestAnimationFrame(tick)
      }
      rafRef.current = requestAnimationFrame(tick)
    },
    [load, duration, stopNode, paint, currentTime]
  )

  const pause = useCallback(() => {
    const time = currentTime()
    stopNode()
    offsetRef.current = time
    setPlaying(false)
    paint(time)
  }, [currentTime, stopNode, paint])

  const seek = useCallback(
    (time: number) => {
      const next = clampTime(time, duration)
      if (nodeRef.current) {
        startAt(next)
      } else {
        offsetRef.current = next
        paint(next)
      }
    },
    [duration, startAt, paint]
  )

  // Stop the sound when the player goes away (reset, re-record, unmount).
  useEffect(() => stopNode, [stopNode])

  useEffect(() => {
    if (load.state === "ready") paint(offsetRef.current)
  }, [load, paint])

  function toggle() {
    if (load.state !== "ready") return
    if (nodeRef.current) pause()
    else startAt(offsetRef.current)
  }

  function onPointerDown(event: PointerEvent<HTMLDivElement>) {
    if (load.state !== "ready" || event.button !== 0) return
    const track = event.currentTarget
    track.setPointerCapture(event.pointerId)
    // Quiet while scrubbing; carry on from the new spot on release.
    dragRef.current = { resume: nodeRef.current !== null }
    if (nodeRef.current) {
      const time = currentTime()
      stopNode()
      offsetRef.current = time
    }
    scrubTo(event.clientX, track)
  }

  function onPointerMove(event: PointerEvent<HTMLDivElement>) {
    if (!dragRef.current) return
    scrubTo(event.clientX, event.currentTarget)
  }

  function onPointerUp(event: PointerEvent<HTMLDivElement>) {
    const drag = dragRef.current
    if (!drag) return
    dragRef.current = null
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
    if (drag.resume) startAt(offsetRef.current)
    else setPlaying(false)
  }

  function scrubTo(clientX: number, track: HTMLDivElement) {
    const rect = track.getBoundingClientRect()
    const time = seekFromPointer(clientX, rect.left, rect.width, duration)
    offsetRef.current = time
    paint(time)
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === " " || event.key === "Enter") {
      event.preventDefault()
      toggle()
      return
    }
    const next = seekForKey(event.key, currentTime(), duration)
    if (next === null) return
    event.preventDefault()
    seek(next)
  }

  const ready = load.state === "ready"
  const dots = waveform === "dots"
  const bar = dots ? 3 : 2
  const gap = dots ? 2.5 : 1.5
  const bars = Math.max(0, Math.floor((width + gap) / (bar + gap)))
  const heights = ready
    ? resamplePeaks(load.peaks, bars).map((peak) => barHeight(peak))
    : new Array<number>(bars).fill(barHeight(0))
  const total = formatElapsed(duration * 1000)

  const wave = (className: string) => (
    <svg
      width={width}
      height={TRACK_HEIGHT}
      viewBox={`0 0 ${width} ${TRACK_HEIGHT}`}
      className={cn("absolute inset-0 block", className)}
      aria-hidden="true"
      focusable="false"
    >
      {heights.map((height, i) => {
        const x = i * (bar + gap)
        if (dots) {
          const spread = (height - barHeight(0)) * (TRACK_HEIGHT / 2 - bar)
          return (
            <g key={i}>
              <circle
                cx={x + bar / 2}
                cy={TRACK_HEIGHT / 2 - spread / 2}
                r={bar / 2}
              />
              <circle
                cx={x + bar / 2}
                cy={TRACK_HEIGHT / 2 + spread / 2}
                r={bar / 2}
              />
            </g>
          )
        }
        const h = Math.max(bar, height * TRACK_HEIGHT)
        return (
          <rect
            key={i}
            x={x}
            y={(TRACK_HEIGHT - h) / 2}
            width={bar}
            height={h}
            rx={bar / 2}
          />
        )
      })}
    </svg>
  )

  if (load.state === "failed") {
    return (
      <p
        data-slot="voice-player"
        className={cn("text-xs text-muted-foreground tabular-nums", className)}
      >
        {total}
      </p>
    )
  }

  return (
    <div
      data-slot="voice-player"
      className={cn("flex min-w-0 items-center gap-2.5", className)}
      {...props}
    >
      <button
        type="button"
        onClick={toggle}
        disabled={!ready}
        aria-label={playing ? labels.pause : labels.play}
        className={cn(
          "relative inline-flex size-7 shrink-0 items-center justify-center rounded-full bg-background text-foreground shadow-xs ring-1 ring-foreground/10 outline-none",
          "before:absolute before:-inset-1 before:rounded-full before:content-[''] pointer-coarse:before:-inset-2",
          "transition-[box-shadow,scale] duration-150 ease-out active:scale-[0.94]",
          "hover:ring-foreground/20 focus-visible:ring-3 focus-visible:ring-ring/40",
          "disabled:cursor-default disabled:text-muted-foreground disabled:active:scale-100"
        )}
      >
        {playing ? (
          <PauseIcon className="size-3" weight="fill" aria-hidden="true" />
        ) : (
          <PlayIcon
            className="size-3 translate-x-px"
            weight="fill"
            aria-hidden="true"
          />
        )}
      </button>

      <div
        ref={trackRef}
        role="slider"
        tabIndex={ready ? 0 : -1}
        aria-label={labels.position}
        aria-valuemin={0}
        aria-valuemax={Math.round(duration)}
        aria-valuenow={second}
        aria-valuetext={`${formatElapsed(second * 1000)} of ${total}`}
        aria-disabled={!ready || undefined}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onKeyDown={onKeyDown}
        className={cn(
          "relative h-7 min-w-0 flex-1 cursor-pointer rounded-sm outline-none select-none",
          // Vertical swipes still scroll the page; horizontal ones scrub.
          "touch-pan-y",
          "focus-visible:ring-3 focus-visible:ring-ring/40 focus-visible:ring-offset-2",
          !ready && "cursor-default"
        )}
      >
        {wave(
          cn(
            "fill-[var(--voice-wave-rest,color-mix(in_oklab,var(--color-muted-foreground)_45%,transparent))]",
            !ready && "animate-pulse"
          )
        )}
        <div
          ref={playedRef}
          className="absolute inset-0"
          style={{ clipPath: "inset(0 100% 0 0)" }}
        >
          {wave("fill-[var(--voice-wave,var(--color-foreground))]")}
        </div>
      </div>

      <span
        ref={timeRef}
        className="shrink-0 text-xs text-muted-foreground tabular-nums"
      >
        {formatPlayback(0, duration)}
      </span>
    </div>
  )
}

async function decode(bytes: ArrayBuffer) {
  const Offline =
    window.OfflineAudioContext ??
    (
      window as unknown as {
        webkitOfflineAudioContext?: typeof OfflineAudioContext
      }
    ).webkitOfflineAudioContext
  if (Offline) {
    try {
      // decodeAudioData resamples to the context's rate.
      const context = new Offline(1, 1, DECODE_RATE)
      return await context.decodeAudioData(bytes.slice(0))
    } catch {
      // Older Safari only decodes at hardware rates; fall through.
    }
  }
  const context = getAudioContext()
  if (!context) throw new Error("No Web Audio")
  return context.decodeAudioData(bytes)
}

"use client"

/**
 * useVoiceRecorder — microphone, MediaRecorder and level metering for the
 * Voice Input component, usable on its own for a custom UI.
 *
 * It owns everything between "the user pressed record" and "here is a
 * finished take": the permission request, device choice (remembered across
 * visits), auto gain, pause/resume, the clock, the max-length cutoff, silence
 * detection and every way that can fail. What happens to the take afterwards
 * — sending it, holding it for review — is the caller's business.
 *
 * Part of the Launch Studio Labs Voice Input component.
 * https://labs.launchstudio.space/voice-input
 */

import { useCallback, useEffect, useRef, useState } from "react"
import { getAudioContext } from "voice-glow"

import {
  isSilentTake,
  listInputs,
  meterLevel,
  peakOf,
  pickRecordingMime,
  resolveInputDevice,
  rmsOf,
  type AudioInput,
} from "@/lib/voice-recording"

export type VoiceRecorderStatus =
  "idle" | "requesting" | "recording" | "paused" | "stopping"

/**
 * Why the microphone could not be used, or why a take was thrown away.
 * - `unsupported`: no getUserMedia / MediaRecorder in this browser
 * - `insecure`: the page is not a secure context (https or localhost)
 * - `denied`: the user or the browser blocked microphone access
 * - `no-device`: there is no microphone, or the chosen one is gone
 * - `too-short`: the take ended before `minDurationMs`
 * - `error`: anything else the browser threw
 */
export type VoiceRecorderProblem =
  "unsupported" | "insecure" | "denied" | "no-device" | "too-short" | "error"

export interface VoiceTake {
  blob: Blob
  mimeType: string
  /** Recorded time, pauses excluded. */
  durationMs: number
  /**
   * The meter saw flat silence for the whole take: a muted, virtual or
   * OS-blocked input. Worth telling apart from "they mumbled".
   */
  silent: boolean
}

export interface UseVoiceRecorderOptions {
  /**
   * Browser automatic gain control. On by default: with it off, quiet
   * microphones arrive too faint for transcription models, which answer a
   * barely-there voice with an empty transcript.
   */
  autoGainControl?: boolean
  echoCancellation?: boolean
  noiseSuppression?: boolean
  /** The take stops itself here. Default 5 minutes. */
  maxDurationMs?: number
  /** Shorter takes are discarded as `too-short`. Default 700ms. */
  minDurationMs?: number
  /** With no signal this long into a take, `quiet` turns true. Default 2.5s. */
  quietAfterMs?: number
  /**
   * localStorage key the chosen microphone is remembered under, or `false`
   * to forget it with the page.
   */
  rememberInput?: string | false
  /**
   * Replaces `navigator.mediaDevices.getUserMedia`. For tests, demos and
   * custom sources (a synthetic stream, a WebRTC track).
   */
  getStream?: (constraints: MediaStreamConstraints) => Promise<MediaStream>
  /** A finished take. Not called for cancelled or too-short takes. */
  onTake?: (take: VoiceTake) => void
}

const DEFAULT_INPUT_KEY = "voice-input.device"

export function useVoiceRecorder({
  autoGainControl = true,
  echoCancellation = true,
  noiseSuppression = true,
  maxDurationMs = 5 * 60_000,
  minDurationMs = 700,
  quietAfterMs = 2500,
  rememberInput = DEFAULT_INPUT_KEY,
  getStream,
  onTake,
}: UseVoiceRecorderOptions = {}) {
  const [status, setStatus] = useState<VoiceRecorderStatus>("idle")
  const [problem, setProblem] = useState<VoiceRecorderProblem | null>(null)
  const [stream, setStream] = useState<MediaStream | null>(null)
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null)
  const [inputs, setInputs] = useState<AudioInput[]>([])
  const [activeInput, setActiveInput] = useState<AudioInput | null>(null)
  const [elapsedMs, setElapsedMs] = useState(0)
  const [quiet, setQuiet] = useState(false)

  const recorderRef = useRef<MediaRecorder | null>(null)
  const streamRef = useRef<MediaStream | null>(null)
  const chunksRef = useRef<Blob[]>([])
  /** Recorded time banked before the current run (pauses split runs). */
  const bankedRef = useRef(0)
  /** When the current run started, or 0 while paused. */
  const runStartRef = useRef(0)
  const timerRef = useRef(0)
  const finishingRef = useRef(false)
  const unmountedRef = useRef(false)
  const meterRef = useRef<{
    stop: () => void
    peak: () => number | null
  } | null>(null)
  const levelRef = useRef(0)

  // The latest options, read from async callbacks without re-subscribing.
  const optionsRef = useRef({
    autoGainControl,
    echoCancellation,
    noiseSuppression,
    maxDurationMs,
    minDurationMs,
    quietAfterMs,
    rememberInput,
    getStream,
    onTake,
  })
  useEffect(() => {
    optionsRef.current = {
      autoGainControl,
      echoCancellation,
      noiseSuppression,
      maxDurationMs,
      minDurationMs,
      quietAfterMs,
      rememberInput,
      getStream,
      onTake,
    }
  })

  const recordedMs = useCallback(() => {
    const run = runStartRef.current ? Date.now() - runStartRef.current : 0
    return bankedRef.current + run
  }, [])

  const stopTimer = useCallback(() => {
    window.clearInterval(timerRef.current)
    timerRef.current = 0
  }, [])

  const stopMeter = useCallback(() => {
    meterRef.current?.stop()
    meterRef.current = null
    levelRef.current = 0
    setAnalyser(null)
  }, [])

  const releaseMic = useCallback(() => {
    stopTimer()
    stopMeter()
    streamRef.current?.getTracks().forEach((track) => track.stop())
    streamRef.current = null
    recorderRef.current = null
    setStream(null)
  }, [stopMeter, stopTimer])

  const refreshInputs = useCallback(async () => {
    if (!navigator.mediaDevices?.enumerateDevices) return []
    try {
      const next = listInputs(await navigator.mediaDevices.enumerateDevices())
      // Labels stay empty until permission is granted; a list of blank
      // "Microphone 1, 2" isn't worth showing.
      const labelled =
        next.length > 0 && !/^Microphone \d+$/.test(next[0].label)
      if (!unmountedRef.current) setInputs(labelled ? next : [])
      return next
    } catch {
      return []
    }
  }, [])

  // Plugging in a headset or switching the system default updates the menu.
  useEffect(() => {
    const devices = navigator.mediaDevices
    if (!devices?.addEventListener) return
    const onChange = () => void refreshInputs()
    devices.addEventListener("devicechange", onChange)
    // Labels are already readable when permission was granted on an earlier
    // visit, so the picker can show before the first take.
    const initial = window.setTimeout(onChange, 0)
    return () => {
      window.clearTimeout(initial)
      devices.removeEventListener("devicechange", onChange)
    }
  }, [refreshInputs])

  useEffect(() => {
    unmountedRef.current = false
    return () => {
      unmountedRef.current = true
      const recorder = recorderRef.current
      releaseMic()
      if (recorder && recorder.state !== "inactive") {
        try {
          recorder.stop()
        } catch {
          // The track ending already stopped it.
        }
      }
    }
  }, [releaseMic])

  function startMeter(next: MediaStream, context: AudioContext | null) {
    stopMeter()
    if (!context) return
    let source: MediaStreamAudioSourceNode
    let node: AnalyserNode
    let sink: GainNode
    try {
      source = context.createMediaStreamSource(next)
      node = context.createAnalyser()
      node.fftSize = 1024
      node.smoothingTimeConstant = 0.6
      // Safari only runs a graph that reaches the destination; a muted gain
      // keeps it pulling without playing the microphone back.
      sink = context.createGain()
      sink.gain.value = 0
      source.connect(node)
      node.connect(sink)
      sink.connect(context.destination)
    } catch {
      return
    }
    const samples = new Float32Array(node.fftSize)
    let peak = 0
    let frames = 0
    let raf = 0
    const tick = () => {
      node.getFloatTimeDomainData(samples)
      // Paused runs don't count toward the silence check.
      if (context.state === "running" && runStartRef.current) {
        frames += 1
        peak = Math.max(peak, peakOf(samples))
      }
      const target = meterLevel(rmsOf(samples))
      // Fast attack, slower release: reads like a VU meter, not a flicker.
      const level = levelRef.current
      levelRef.current =
        level + (target - level) * (target > level ? 0.5 : 0.12)
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    setAnalyser(node)
    meterRef.current = {
      stop: () => {
        cancelAnimationFrame(raf)
        try {
          source.disconnect()
          node.disconnect()
          sink.disconnect()
        } catch {
          // Already disconnected.
        }
      },
      // Only trust the peak once the graph has been running for a moment;
      // a suspended context reads as zeros.
      peak: () => (frames > 20 ? peak : null),
    }
  }

  function constraints(deviceId: string | null): MediaStreamConstraints {
    const { autoGainControl, echoCancellation, noiseSuppression } =
      optionsRef.current
    return {
      audio: {
        autoGainControl,
        echoCancellation,
        noiseSuppression,
        ...(deviceId ? { deviceId: { exact: deviceId } } : {}),
      },
    }
  }

  async function requestMicrophone(storedId: string | null) {
    const custom = optionsRef.current.getStream
    const request = (c: MediaStreamConstraints) =>
      custom ? custom(c) : navigator.mediaDevices.getUserMedia(c)
    let deviceId = storedId
    if (deviceId && !custom) {
      // Drop a remembered device that is no longer plugged in. Before
      // permission enumerateDevices hides ids, so keep it and let `exact`
      // decide.
      try {
        const listed = listInputs(
          await navigator.mediaDevices.enumerateDevices()
        )
        const known = listed.some((input) => input.deviceId !== "")
        if (known && !resolveInputDevice(listed, deviceId)) deviceId = null
      } catch {
        // Fall through with the stored id.
      }
    }
    if (deviceId) {
      try {
        return await request(constraints(deviceId))
      } catch (error) {
        const name = errorName(error)
        if (name === "NotAllowedError" || name === "SecurityError") throw error
        // The remembered device vanished or refused: forget it, use default.
        writeStoredInput(optionsRef.current.rememberInput, null)
      }
    }
    try {
      return await request(constraints(null))
    } catch (error) {
      const name = errorName(error)
      if (
        name === "NotAllowedError" ||
        name === "SecurityError" ||
        name === "NotFoundError"
      ) {
        throw error
      }
      // Some engines reject the processing constraints outright.
      return request({ audio: true })
    }
  }

  async function showActiveInput(track: MediaStreamTrack | undefined) {
    const list = await refreshInputs()
    if (!track || unmountedRef.current) return
    const id = track.getSettings?.().deviceId ?? ""
    const match =
      list.find((input) => input.deviceId === id) ??
      // Safari can omit deviceId from settings; the label still matches.
      list.find((input) => track.label && input.label === track.label)
    setActiveInput(
      match ??
        // A custom source's track label is a node name, not a device.
        (track.label && !optionsRef.current.getStream
          ? { deviceId: id, label: track.label }
          : null)
    )
  }

  function startClock() {
    stopTimer()
    timerRef.current = window.setInterval(() => {
      const ms = recordedMs()
      setElapsedMs(ms)
      const { quietAfterMs, maxDurationMs } = optionsRef.current
      if (ms >= quietAfterMs) {
        setQuiet(isSilentTake(meterRef.current?.peak() ?? null))
      }
      if (ms >= maxDurationMs) void stop()
    }, 200)
  }

  async function begin(deviceId: string | null) {
    setStatus("requesting")
    // Created inside the click: Safari only lets an AudioContext start from
    // a user gesture. It is the same context Voice Glow analyses with.
    const context = getAudioContext()
    let next: MediaStream
    try {
      next = await requestMicrophone(deviceId)
    } catch (error) {
      if (unmountedRef.current) return false
      const name = errorName(error)
      setProblem(
        name === "NotAllowedError" || name === "SecurityError"
          ? "denied"
          : name === "NotFoundError" || name === "OverconstrainedError"
            ? "no-device"
            : "error"
      )
      setStatus("idle")
      return false
    }
    if (unmountedRef.current) {
      next.getTracks().forEach((track) => track.stop())
      return false
    }

    let recorder: MediaRecorder
    try {
      const mime = pickRecordingMime((type) =>
        MediaRecorder.isTypeSupported(type)
      )
      recorder = new MediaRecorder(next, mime ? { mimeType: mime } : undefined)
    } catch {
      next.getTracks().forEach((track) => track.stop())
      setProblem("unsupported")
      setStatus("idle")
      return false
    }

    chunksRef.current = []
    recorder.ondataavailable = (event) => {
      if (event.data.size) chunksRef.current.push(event.data)
    }
    recorderRef.current = recorder
    streamRef.current = next
    setStream(next)

    const track = next.getAudioTracks()[0]
    // Unplugging the microphone ends the track: keep what was said.
    track?.addEventListener("ended", () => {
      if (recorderRef.current === recorder) void stop()
    })
    void showActiveInput(track)

    if (context && context.state === "suspended") {
      await context.resume().catch(() => {})
    }
    startMeter(next, context)

    bankedRef.current = 0
    runStartRef.current = Date.now()
    recorder.start(250)
    setElapsedMs(0)
    setQuiet(false)
    setStatus("recording")
    startClock()
    return true
  }

  /** Stop the recorder and resolve with every chunk it produced. */
  function stopRecorder(recorder: MediaRecorder) {
    return new Promise<Blob>((resolve) => {
      // The final dataavailable fires before stop, so the blob is complete.
      recorder.addEventListener(
        "stop",
        () => {
          resolve(
            new Blob(chunksRef.current, {
              type: recorder.mimeType || "audio/webm",
            })
          )
        },
        { once: true }
      )
      recorder.stop()
    })
  }

  /** Ask for the microphone and start a take. Call it from a click. */
  async function start() {
    if (status !== "idle") return false
    setProblem(null)
    if (typeof window !== "undefined" && window.isSecureContext === false) {
      setProblem("insecure")
      return false
    }
    if (!optionsRef.current.getStream && !canRecord()) {
      setProblem("unsupported")
      return false
    }
    return begin(readStoredInput(optionsRef.current.rememberInput))
  }

  /** Finish the take and hand it to `onTake`. */
  async function stop() {
    if (finishingRef.current) return null
    const recorder = recorderRef.current
    if (!recorder || recorder.state === "inactive") return null
    finishingRef.current = true
    const durationMs = recordedMs()
    runStartRef.current = 0
    stopTimer()
    setStatus("stopping")
    const peak = meterRef.current?.peak() ?? null
    const blob = await stopRecorder(recorder)
    releaseMic()
    finishingRef.current = false
    if (unmountedRef.current) return null
    setStatus("idle")
    setQuiet(false)
    if (durationMs < optionsRef.current.minDurationMs || blob.size === 0) {
      setProblem("too-short")
      return null
    }
    const take: VoiceTake = {
      blob,
      mimeType: blob.type || "audio/webm",
      durationMs,
      silent: isSilentTake(peak),
    }
    optionsRef.current.onTake?.(take)
    return take
  }

  function pause() {
    const recorder = recorderRef.current
    if (!recorder || recorder.state !== "recording") return
    recorder.pause()
    bankedRef.current = recordedMs()
    runStartRef.current = 0
    setElapsedMs(bankedRef.current)
    setStatus("paused")
  }

  function resume() {
    const recorder = recorderRef.current
    if (!recorder || recorder.state !== "paused") return
    recorder.resume()
    runStartRef.current = Date.now()
    setStatus("recording")
  }

  /** Throw the current take away. Nothing reaches `onTake`. */
  async function cancel() {
    const recorder = recorderRef.current
    if (!recorder || recorder.state === "inactive" || finishingRef.current) {
      return
    }
    finishingRef.current = true
    runStartRef.current = 0
    stopTimer()
    await stopRecorder(recorder)
    releaseMic()
    finishingRef.current = false
    if (unmountedRef.current) return
    setStatus("idle")
    setQuiet(false)
    setElapsedMs(0)
  }

  /**
   * Use another microphone. Mid-take, the take restarts on the new device
   * rather than stitching two recordings together.
   */
  async function chooseInput(deviceId: string) {
    writeStoredInput(optionsRef.current.rememberInput, deviceId)
    const input = inputs.find((item) => item.deviceId === deviceId) ?? null
    if (status === "recording" || status === "paused") {
      await cancel()
      await begin(deviceId)
      return { restarted: true, input }
    }
    if (input) setActiveInput(input)
    return { restarted: false, input }
  }

  return {
    status,
    problem,
    clearProblem: useCallback(() => setProblem(null), []),
    /** The live microphone stream while a take is running. */
    stream,
    /** Analyser on the live stream, for drawing a waveform. */
    analyser,
    /** The smoothed level, 0–1. Read it per frame; it is not state. */
    getLevel: useCallback(() => levelRef.current, []),
    elapsedMs,
    /** No signal at all for `quietAfterMs` into the take. */
    quiet,
    inputs,
    activeInput,
    start,
    stop,
    pause,
    resume,
    cancel,
    chooseInput,
  }
}

export type VoiceRecorder = ReturnType<typeof useVoiceRecorder>

function errorName(error: unknown) {
  return error instanceof DOMException || error instanceof Error
    ? error.name
    : ""
}

export function canRecord() {
  return (
    typeof navigator !== "undefined" &&
    typeof navigator.mediaDevices?.getUserMedia === "function" &&
    typeof MediaRecorder !== "undefined"
  )
}

function readStoredInput(key: string | false) {
  if (!key) return null
  try {
    return window.localStorage.getItem(key)
  } catch {
    return null
  }
}

function writeStoredInput(key: string | false, deviceId: string | null) {
  if (!key) return
  try {
    if (deviceId) window.localStorage.setItem(key, deviceId)
    else window.localStorage.removeItem(key)
  } catch {
    // Private mode: the choice just lasts for this take.
  }
}

/**
 * Voice Input — pure helpers for recording in the browser and handing the
 * audio to a transcription API. No DOM or framework imports, so they run in
 * a test runner or on the server (`audioExtension`, `isAcceptedAudio`).
 *
 * Part of the Launch Studio Labs Voice Input component.
 * https://labs.launchstudio.space/voice-input
 */

/**
 * Recorder formats in order of preference. Opus in WebM is what Chromium
 * records natively; Safari records AAC in MP4 (and WebM only from 18.4).
 * Every entry maps to an extension OpenAI's transcription endpoint accepts —
 * it infers the format from the filename.
 */
export const RECORDING_MIME_TYPES = [
  "audio/webm;codecs=opus",
  "audio/webm",
  "audio/mp4;codecs=mp4a.40.2",
  "audio/mp4",
  "audio/ogg;codecs=opus",
] as const

/** First supported recorder format, or "" to let the browser choose. */
export function pickRecordingMime(isSupported: (type: string) => boolean) {
  for (const type of RECORDING_MIME_TYPES) {
    try {
      if (isSupported(type)) return type
    } catch {
      // Some engines throw on unknown types instead of returning false.
    }
  }
  return ""
}

/** "audio/webm;codecs=opus" → "audio/webm". */
export function baseMime(type: string) {
  return type.split(";")[0].trim().toLowerCase()
}

/**
 * File extension for a recorded audio type. OpenAI reads the format from
 * the extension, so it has to describe the container the browser actually
 * produced.
 */
export function audioExtension(contentType: string) {
  const type = baseMime(contentType)
  if (type.includes("mp4") || type.includes("m4a") || type.includes("aac")) {
    return "m4a"
  }
  if (type.includes("mpeg") || type.includes("mp3")) return "mp3"
  if (type.includes("ogg")) return "ogg"
  if (type.includes("wav")) return "wav"
  if (type.includes("flac")) return "flac"
  return "webm"
}

export function isAcceptedAudio(contentType: string) {
  const type = baseMime(contentType)
  return (
    type.startsWith("audio/") || type === "video/webm" || type === "video/mp4"
  )
}

/**
 * Peak sample level (0–1) below which a whole take counts as silent: about
 * -60 dBFS. A working microphone in a quiet room never stays this low while
 * someone speaks; a muted, virtual or OS-blocked input delivers exact zeros.
 */
export const SILENCE_PEAK = 0.001

export function isSilentTake(peak: number | null) {
  return peak !== null && peak < SILENCE_PEAK
}

/** Peak absolute sample of a time-domain buffer (−1…1 floats). */
export function peakOf(samples: ArrayLike<number>) {
  let peak = 0
  for (let i = 0; i < samples.length; i++) {
    const value = Math.abs(samples[i])
    if (value > peak) peak = value
  }
  return peak
}

/** Root mean square of a time-domain buffer (−1…1 floats). */
export function rmsOf(samples: ArrayLike<number>) {
  if (samples.length === 0) return 0
  let sum = 0
  for (let i = 0; i < samples.length; i++) sum += samples[i] * samples[i]
  return Math.sqrt(sum / samples.length)
}

/**
 * Map RMS to a 0–1 meter value on a decibel scale: -60 dBFS reads empty,
 * -12 dBFS (a close, normal speaking voice) reads full.
 */
export function meterLevel(rms: number) {
  if (!(rms > 0)) return 0
  const db = 20 * Math.log10(rms)
  const level = (db + 60) / 48
  return level < 0 ? 0 : level > 1 ? 1 : level
}

export interface AudioInput {
  deviceId: string
  label: string
  /** Chromium's "default" entry, which follows the system input setting. */
  isDefault?: boolean
}

/**
 * The deviceId to ask getUserMedia for: the stored choice while that device
 * is still connected, otherwise null (use the browser's default).
 */
export function resolveInputDevice(
  inputs: readonly AudioInput[],
  storedId: string | null
) {
  if (!storedId) return null
  return inputs.some((input) => input.deviceId === storedId) ? storedId : null
}

/**
 * Display name for an input. Chromium prefixes the system default with
 * "Default - "; labels are empty until microphone permission is granted.
 */
export function inputLabel(label: string, index: number) {
  const clean = label.replace(/^default\s*-\s*/i, "").trim()
  return clean || `Microphone ${index + 1}`
}

/**
 * The audio inputs worth listing. Chromium adds a "default" entry that
 * follows the system input (kept, first, flagged) and a Windows-only
 * "communications" alias (dropped).
 */
export function listInputs(
  devices: readonly {
    kind: string
    deviceId: string
    label: string
  }[]
): AudioInput[] {
  const audio = devices.filter(
    (device) =>
      device.kind === "audioinput" &&
      device.deviceId &&
      device.deviceId !== "communications"
  )
  const ordered = [
    ...audio.filter((device) => device.deviceId === "default"),
    ...audio.filter((device) => device.deviceId !== "default"),
  ]
  return ordered.map((device, index) => ({
    deviceId: device.deviceId,
    label: inputLabel(device.label, index),
    ...(device.deviceId === "default" ? { isDefault: true } : {}),
  }))
}

/** "m:ss" for a recording clock. */
export function formatElapsed(ms: number) {
  const total = Math.max(0, Math.floor(ms / 1000))
  const minutes = Math.floor(total / 60)
  const seconds = total % 60
  return `${minutes}:${String(seconds).padStart(2, "0")}`
}

// ── Playback preview ──

/**
 * Per-bucket peaks (0–1) of a decoded recording, normalised to its loudest
 * moment so a quiet take still reads. Runs once per recording: an 8-minute
 * take at 24 kHz is ~11.5M samples, a single linear pass.
 */
export function computePeaks(
  channels: readonly ArrayLike<number>[],
  buckets: number
) {
  const length = channels[0]?.length ?? 0
  const count = Math.max(0, Math.floor(buckets))
  const peaks = new Array<number>(count).fill(0)
  if (!length || !count) return peaks
  for (let b = 0; b < count; b++) {
    const start = Math.floor((b * length) / count)
    const end = Math.max(start + 1, Math.floor(((b + 1) * length) / count))
    let peak = 0
    for (const channel of channels) {
      for (let i = start; i < end && i < length; i++) {
        const value = Math.abs(channel[i])
        if (value > peak) peak = value
      }
    }
    peaks[b] = peak
  }
  return normalizePeaks(peaks)
}

function normalizePeaks(peaks: number[]) {
  let max = 0
  for (const peak of peaks) if (peak > max) max = peak
  if (max <= 0) return peaks.map(() => 0)
  return peaks.map((peak) => Math.min(1, peak / max))
}

/**
 * Fit precomputed peaks to the number of bars that fit on screen, keeping
 * the loudest value in each group so short spikes don't vanish.
 */
export function resamplePeaks(peaks: readonly number[], count: number) {
  const bars = Math.max(0, Math.floor(count))
  if (!bars || !peaks.length) return new Array<number>(bars).fill(0)
  const out = new Array<number>(bars)
  for (let b = 0; b < bars; b++) {
    const start = Math.floor((b * peaks.length) / bars)
    const end = Math.max(start + 1, Math.floor(((b + 1) * peaks.length) / bars))
    let peak = 0
    for (let i = start; i < end && i < peaks.length; i++) {
      if (peaks[i] > peak) peak = peaks[i]
    }
    out[b] = peak
  }
  return out
}

/** Bar height as a fraction of the track: silence still shows as a dot. */
export function barHeight(peak: number, min = 0.12) {
  const value = Number.isFinite(peak) ? Math.min(1, Math.max(0, peak)) : 0
  return min + (1 - min) * value
}

/** Playback position (seconds) for a pointer at clientX over the track. */
export function seekFromPointer(
  clientX: number,
  left: number,
  width: number,
  duration: number
) {
  if (!(width > 0) || !(duration > 0)) return 0
  const fraction = Math.min(1, Math.max(0, (clientX - left) / width))
  return fraction * duration
}

/** Clamp a seek (seconds) into the recording. */
export function clampTime(time: number, duration: number) {
  if (!(duration > 0) || !Number.isFinite(time)) return 0
  return Math.min(duration, Math.max(0, time))
}

/** New position for a slider key, or null when the key isn't a seek key. */
export function seekForKey(
  key: string,
  current: number,
  duration: number,
  step = 5
) {
  switch (key) {
    case "ArrowRight":
    case "ArrowUp":
      return clampTime(current + step, duration)
    case "ArrowLeft":
    case "ArrowDown":
      return clampTime(current - step, duration)
    case "PageUp":
      return clampTime(current + Math.max(step, duration / 10), duration)
    case "PageDown":
      return clampTime(current - Math.max(step, duration / 10), duration)
    case "Home":
      return 0
    case "End":
      return clampTime(duration, duration)
    default:
      return null
  }
}

/** "0:12 / 1:04" — position and length of a recording, in seconds. */
export function formatPlayback(current: number, duration: number) {
  return `${formatElapsed(current * 1000)} / ${formatElapsed(duration * 1000)}`
}
